    if s < 5 and not(t > 3):
        return 0
    else:
        return 1
a = ((9, 9), (9, 10), (8, 5), (11, 6), (-11, 10), (-5, 9), (-10, 10), (4, 5), (8, 6))
kol = 0
for i in range(9):
    kol += f(a[i][0], a[i][1])
print(kol)

